"use strict";(globalThis.webpackChunkgrc||=[]).push([[25130],{52166(e){e.exports=JSON.parse('{"citeKey":"zhang2017evaluatinggpgpu","slug":"zhang-2017-evaluating-gpgpu-8dc8","title":"Evaluating GPGPU Memory Performance Through the C-AMAT Model","authors":["N. Zhang","C. Jiang","X.-H. Sun","S. Song"],"venue":"The ACM SIGHPC 1st International Workshop on Memory Centric Programming for HPC (MCHPC 2017), in conjunction with SC\'17, Denver, CO. USA2017. pp. 35-39","type":"Workshop","entryType":"inproceedings","date":"November, 2017","year":2017,"era":"iit","month":11,"doi":"10.1145/3145617.3158214","abstract":"General Purpose Graphics Processing Units (GPGPU) have become a popular platform to accelerate high performance applications. Although they provide exceptional computing power, GPGPU impose significant pressure on the off-chip memory system. Evaluating, understanding, and improving GPGPU data access delay has become an important research topic in high-performance computing. In this study, we utilize the newly proposed GPGPU/C-AMAT (Concurrent Average Memory Access Time) model to quantitatively evaluate GPGPU memory performance. Specifically, we extend the current C-AMAT model to include a GPGPU-specific modeling component and then provide its evaluation results.","hasAbstract":true,"lede":"General Purpose Graphics Processing Units (GPGPU) have become a popular platform to accelerate high performance applications.","links":{"pdf":"https://grc.iit.edu/papers/2017/zhang-2017-evaluating-gpgpu-8dc8.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);